DO $$
DECLARE
  rec RECORD;
  cur CURSOR FOR SELECT ticket_id, priority_level, sla_hours_remaining FROM support_tickets ORDER BY ticket_id ASC;
  new_priority INTEGER;
  new_sla DECIMAL(10,2);
BEGIN
  OPEN cur;
  LOOP
    FETCH cur INTO rec;
    EXIT WHEN NOT FOUND;

    new_priority := rec.priority_level;
    new_sla := rec.sla_hours_remaining;

    -- Rule 1: If sla_hours_remaining <= 4.00, increase priority_level by 1 (max 4)
    IF new_sla <= 4.00 THEN
      new_priority := LEAST(new_priority + 1, 4);
    END IF;

    -- Rule 2: If priority_level is now 4, reduce sla_hours_remaining by 2.50
    IF new_priority = 4 THEN
      new_sla := new_sla - 2.50;
    END IF;

    -- Rule 3: If sla_hours_remaining is now < 0.00, set to 0.00
    IF new_sla < 0.00 THEN
      new_sla := 0.00;
    END IF;

    UPDATE support_tickets
    SET priority_level = new_priority,
        sla_hours_remaining = new_sla
    WHERE ticket_id = rec.ticket_id;
  END LOOP;
  CLOSE cur;
END $$;

SELECT * FROM support_tickets ORDER BY ticket_id ASC;
